//! Candidate-local native Rust witness for WP-RMT-002 Workflow.
#[derive(Debug,Clone,PartialEq,Eq)]pub struct WorkflowObservation{pub observed_step_ids:Vec<&'static str>,pub scope:&'static str,pub failure_continuation_policy:&'static str,pub recovery_intents:Vec<&'static str>,pub compensation_policy:&'static str,pub direct_effects_executed:Vec<&'static str>,pub binding_state:&'static str,pub s1_binding_state:&'static str,pub guard_bypass_observed:bool,pub lifecycle_transition_bypass_observed:bool,pub durable_fact_preservation:&'static str}
#[derive(Debug,Clone,PartialEq,Eq)]pub struct ScenarioResult{pub trace:Vec<&'static str>,pub outcome:&'static str,pub failed_step_id:Option<&'static str>,pub recovery_intents:Vec<&'static str>,pub compensation_execution:bool,pub durable_fact_preservation:&'static str}
pub const ORDER:[&str;4]=["validate","decide","persist","publish"];
pub fn baseline()->WorkflowObservation{WorkflowObservation{observed_step_ids:ORDER.to_vec(),scope:"intra-feature",failure_continuation_policy:"stop-and-return-structured-outcome",recovery_intents:vec![],compensation_policy:"forward-recovery-only",direct_effects_executed:vec![],binding_state:"current",s1_binding_state:"current",guard_bypass_observed:false,lifecycle_transition_bypass_observed:false,durable_fact_preservation:"preserve-durable-facts"}}
pub fn evaluate(o:&WorkflowObservation)->Vec<&'static str>{let mut f=Vec::new();if o.observed_step_ids.len()<ORDER.len()||ORDER.iter().any(|id|!o.observed_step_ids.contains(id)){f.push("RMT_WF_STEP_SKIP");}else{let unique=o.observed_step_ids.iter().collect::<std::collections::HashSet<_>>();if unique.len()!=o.observed_step_ids.len(){f.push("RMT_WF_STEP_DUPLICATE");}else if o.observed_step_ids!=ORDER{f.push("RMT_WF_STEP_REORDER");}}if o.scope!="intra-feature"{f.push("RMT_WF_SCOPE_DRIFT");}if o.failure_continuation_policy!="stop-and-return-structured-outcome"{f.push("RMT_WF_FAILURE_CONTINUATION_MISMATCH");}if o.compensation_policy!="forward-recovery-only"||!o.recovery_intents.is_empty()||o.durable_fact_preservation!="preserve-durable-facts"{f.push("RMT_WF_COMPENSATION_OVERCLAIM");}if !o.direct_effects_executed.is_empty(){f.push("RMT_WF_EXECUTES_EFFECT");}if o.binding_state!="current"{f.push("RMT_WF_STALE_BINDING");}if o.guard_bypass_observed{f.push("RMT_WF_GUARD_BYPASS");}if o.lifecycle_transition_bypass_observed{f.push("RMT_WF_LIFECYCLE_TRANSITION_BYPASS");}f}
pub fn evaluate_s1(o:&WorkflowObservation)->Vec<&'static str>{if o.s1_binding_state=="current"{vec![]}else{vec!["RMT_S1_STALE_BINDING"]}}
pub fn run_scenario(fail_publish:bool)->ScenarioResult{if fail_publish{ScenarioResult{trace:ORDER[..3].to_vec(),outcome:"settlement-failed",failed_step_id:Some("publish"),recovery_intents:vec!["forward-recover-settlement"],compensation_execution:false,durable_fact_preservation:"preserve-durable-facts"}}else{ScenarioResult{trace:ORDER.to_vec(),outcome:"settlement-completed",failed_step_id:None,recovery_intents:vec![],compensation_execution:false,durable_fact_preservation:"preserve-durable-facts"}}}
